function orderTable(xs){return '<div class="pro-table"><table><thead><tr><th>Pesanan</th><th>Customer</th><th>Tanggal sewa</th><th>Pembayaran</th><th>Total</th></tr></thead><tbody>'+xs.map(o=>`<tr><td>${E(o.order_number)}</td><td>${E(o.customer_name)}</td><td>${E(o.start_date)} — ${E(o.end_date)}</td><td>${E(({unpaid:'Belum bayar',pending:'Menunggu cek',partial:'Sebagian',paid:'Lunas',rejected:'Ditolak'})[o.payment_status])}</td><td>${M(o.total)}</td></tr>`).join('')+'</tbody></table></div>'}
function orderForm(quote=false){const s=docSettings(),cfg=window.RENTCAM_CMS_CONFIG||{},valid=new Date();valid.setDate(valid.getDate()+7);const banks=cfg.payment?.bankAccounts||[],logo=s.logo?'<img class="bsm-logo-img" src="'+E(s.logo)+'">':'<div class="bsm-logo-letters"><span>B</span><span>S</span><span>M</span></div>';return '<div class="pro-card quotation-sheet qd-editor bsm-quote-editor"><form id="proDirectForm" data-kind="'+(quote?'quotation':'direct_order')+'"><div class="bsm-version"><span>◷ VERSI <b>BARU</b></span><span>Data tersimpan setelah quotation dibuat</span></div><section class="bsm-quotation-card"><div class="bsm-company-head">'+logo+'<div class="bsm-company-info"><h2>'+E(s.company)+'</h2><p>'+E(s.address).replace(/\n/g,'<br>')+'</p><p class="bsm-blue">'+E(s.email)+'</p><p>'+E(s.taxNumber?('NPWP: '+s.taxNumber):s.phone)+'</p></div></div><div class="bsm-quote-center"><h2>'+E(s.quotationTitle)+'</h2><span>Nomor: otomatis setelah disimpan</span><label>Berlaku sampai <input name="valid_until" type="date" value="'+valid.toLocaleDateString('sv-SE')+'" required></label></div><div class="bsm-details-grid"><div><label>PROGRAM NAME <input name="program" value="Sewa Alat Produksi"></label><label>CLIENT <input name="name" minlength="2" maxlength="120" required></label><label>PIC <input name="pic"></label><label>TELP / HP <input name="phone" type="tel" required></label><label>EMAIL <input name="email" type="email"></label><label class="bsm-customer-master">MASTER CUSTOMER <select id="quotationCustomer"><option value="">Customer baru / input manual</option></select></label><small id="quotationCustomerInfo">Memuat Master Customer...</small></div><div><label>PICK UP DATE <input name="start" type="date" min="'+today()+'" value="'+today()+'" required></label><label>SHOOTING DATE <span id="quotationDays">1 hari</span></label><label>RETURN DATE <input name="end" type="date" min="'+today()+'" value="'+today()+'" required></label><label>LOCATION <input name="location" placeholder="Jakarta"></label><label>CREW CALL <input name="crew_call" placeholder="To be confirm"></label></div></div></section><div class="bsm-check-row"><span>Checklist Tentatif = tanggal alat belum fix.</span><div><button type="button" data-tentative-all="1">☑ CHECKLIST ALL</button><button type="button" data-tentative-all="0">□ UNCHECKLIST ALL</button></div></div><div class="pro-table quotation-equipment bsm-equipment-table"><table><thead><tr><th>NO</th><th>PRODUCT</th><th>QTY</th><th>DAYS</th><th>PRICE / DAY</th><th>AMOUNT / DETAIL</th><th></th></tr></thead><tbody id="proItemRows"></tbody></table></div><div class="bsm-add-row">'+B('add-item','🛒 TAMBAH PRODUK')+'</div><hr><section class="bsm-lower-grid"><div><h4>ⓘ CATATAN KHUSUS ORDERAN</h4><textarea name="notes" maxlength="2000" placeholder="Catatan khusus untuk orderan ini..."></textarea><h4>▥ REKENING PEMBAYARAN</h4><select name="bank_id"><option value="">Pilih rekening</option>'+banks.filter(b=>b.active!==false).map(b=>'<option value="'+E(b.id)+'">'+E(b.bank)+' · '+E(b.number)+' · '+E(b.holder)+'</option>').join('')+'</select><h4>SYARAT & KETENTUAN</h4><div class="bsm-terms">'+s.terms.split('\n').filter(t=>t.trim()).map((t,i)=>'<p>'+(i+1)+'. '+E(t.replace(/^\d+[\.\)]\s*/,''))+'</p>').join('')+'</div></div><aside class="bsm-summary"><div><b>SUBTOTAL</b><b id="quotationSubtotal">Rp0</b></div><div class="premium-discount"><div class="premium-discount-head"><span>DISKON</span><small>Pilih satu cara diskon</small></div><div class="premium-discount-options"><label><input type="radio" name="discount_mode" value="none" checked><span>Tanpa diskon<small>Harga normal</small></span></label><label><input type="radio" name="discount_mode" value="overall_percent"><span>Persentase<small>% total</small></span></label><label><input type="radio" name="discount_mode" value="fixed"><span>Nominal<small>Potongan Rp</small></span></label><label><input type="radio" name="discount_mode" value="product"><span>Per produk<small>Checklist alat</small></span></label><label><input type="radio" name="discount_mode" value="days"><span>Hari bayar<small>Sewa 3 bayar 2</small></span></label></div><label data-discount-value hidden><span id="discountValueLabel">Nilai diskon</span><input name="discount_value" type="number" min="0" value="0"></label><label data-free-days hidden>Jumlah hari gratis<input name="free_days" type="number" min="0" value="0"></label></div><div class="bsm-discount"><span>DISKON TAMBAHAN</span><b id="quoteDiscountValue">Rp0</b></div><div><b>SUBTOTAL SETELAH DISKON</b><b id="quoteAfterDiscount">Rp0</b></div><label class="bsm-tax"><span><input name="tax_enabled" type="checkbox"> PPN 11%</span><b id="quoteTaxValue">Rp0</b></label><div class="bsm-grand"><span>TOTAL SETELAH PAJAK</span><b id="quoteFinalValue">Rp0</b></div></aside></section><section class="bsm-signatures"><div><b>APPROVED BY,</b><div class="bsm-sign-placeholder">Persetujuan customer</div><strong>________________</strong><span>Customer</span></div><div><b>PREPARED BY,</b><div class="quote-signature-box"><canvas id="quoteSignature" width="420" height="200"></canvas><span>Tanda tangan di sini</span></div><div class="premium-sign-tools"><button type="button" data-sign-clear>Hapus</button><button type="button" data-sign-download>Simpan PNG</button><label>Upload<input type="file" data-sign-upload accept="image/*" hidden></label></div><strong>'+E(s.signatory||'________________')+'</strong><span>'+E(s.company)+'</span></div></section><footer class="bsm-footer"><b>Warehouse</b><span>'+E(s.address)+'</span><b>Mobile</b><span>'+E(s.phone)+'</span><b>Email</b><span>'+E(s.email)+'</span></footer><div class="quotation-bottom"><p>Konfirmasi stok dan pembayaran diperlukan sebelum rental disetujui.</p><button type="submit">'+(quote?'Simpan penawaran':'Simpan pesanan & quotation')+'</button></div><p data-msg role="status"></p></form></div>'}

let quoteSignDirty=false;
function setupSignature(){const c=document.querySelector('#quoteSignature');if(!c||c.dataset.ready)return;c.dataset.ready='1';const x=c.getContext('2d');x.lineWidth=2.2;x.lineCap='round';x.strokeStyle='#222';let draw=false;const point=e=>{const r=c.getBoundingClientRect(),p=e.touches?.[0]||e;return[(p.clientX-r.left)*c.width/r.width,(p.clientY-r.top)*c.height/r.height]};c.addEventListener('pointerdown',e=>{draw=true;quoteSignDirty=true;const[a,b]=point(e);x.beginPath();x.moveTo(a,b);e.preventDefault()});c.addEventListener('pointermove',e=>{if(!draw)return;const[a,b]=point(e);x.lineTo(a,b);x.stroke();e.preventDefault()});addEventListener('pointerup',()=>draw=false)}
async function uploadAdminBlob(blob,folder,ext){const token=await rpc('rentcam_issue_upload_token',{}),path=encodeURIComponent(String(token).replace(/"/g,''))+'/'+folder+'/'+crypto.randomUUID()+'.'+ext,r=await fetch(SB+'/storage/v1/object/cms-media/'+path,{method:'POST',headers:{apikey:KEY,'Content-Type':blob.type},body:blob});if(!r.ok)throw Error('Upload file gagal');return SB+'/storage/v1/object/public/cms-media/'+path}
async function signatureUrl(){if(!quoteSignDirty)return '';const c=document.querySelector('#quoteSignature'),blob=await new Promise(r=>c.toBlob(r,'image/png'));return uploadAdminBlob(blob,'document-signatures','png')}
async function loadPdf(){if(window.html2pdf)return;await new Promise((ok,no)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/html2pdf.js@0.10.2/dist/html2pdf.bundle.min.js';s.onload=ok;s.onerror=()=>no(Error('Pembuat PDF gagal dimuat'));document.head.append(s)})}
async function makePdf(d){await loadPdf();const filename=(d.kind==='invoice'?'Invoice-':'Quotation-')+d.number.replace(/[^\w-]+/g,'-')+'.pdf',worker=window.html2pdf().set({margin:[8,8],filename,image:{type:'jpeg',quality:.96},html2canvas:{scale:2,useCORS:true},jsPDF:{unit:'mm',format:'a4',orientation:'portrait'}}).from(document.querySelector('#proPrintable')).toPdf();return{blob:await worker.output('blob'),filename}}

let quotationCustomers=[];
async function loadCustomers(){const picker=document.querySelector('#quotationCustomer');if(!picker)return;try{quotationCustomers=await api('rentcam_contacts?select=*&kind=eq.customer&order=name.asc');const phoneKey=p=>String(p||'').replace(/\D/g,'').replace(/^62/,'0'),known=new Set(quotationCustomers.map(c=>phoneKey(c.phone)).filter(Boolean));orders.filter(o=>o.source!=='quotation'&&o.rental_status!=='cancelled').forEach(o=>{const key=phoneKey(o.phone);if(key&&!known.has(key)){known.add(key);quotationCustomers.push({id:'order-'+o.id,name:o.customer_name,phone:o.phone,email:o.email,company:''})}});if(!picker.isConnected)return;picker.innerHTML='<option value="">Customer baru / input manual</option>'+quotationCustomers.map(c=>`<option value="${E(c.id)}">${E(c.name)}${c.company?' · '+E(c.company):''}${c.phone?' · '+E(c.phone):''}</option>`).join('');document.querySelector('#quotationCustomerInfo').textContent=quotationCustomers.length+' customer dari Master Data. Pilih untuk mengisi kontak otomatis.'}catch(e){if(picker.isConnected)document.querySelector('#quotationCustomerInfo').textContent=e.message}}
async function loadProducts(){const f=document.querySelector('#proDirectForm');if(!f)return;try{const data=await rpc('rentcam_admin_stock',{p_start:f.elements.start.value,p_end:f.elements.end.value,p_exclude:null});if(!f.isConnected)return;stock=data;f.querySelectorAll('[data-item]').forEach(select=>{const value=select.value;select.innerHTML='<option value="">Pilih produk dari master</option>'+stock.map(p=>'<option value="'+E(p.id)+'">'+E(p.name)+' · tersedia '+p.available+'</option>').join('');select.value=value});estimate()}catch(e){f.querySelector('[data-msg]').textContent=e.message}}function addItem(){document.querySelector('#proItemRows')?.insertAdjacentHTML('beforeend','<tr class="pro-item-row"><td data-row-number></td><td><select data-item required><option value="">Pilih produk dari master</option>'+stock.map(p=>'<option value="'+E(p.id)+'">'+E(p.name)+' · tersedia '+p.available+'</option>').join('')+'</select><small data-row-stock></small></td><td><input data-quantity type="number" min="1" max="100" value="1" required></td><td data-row-days>1</td><td data-row-price>Rp0</td><td><strong data-row-amount>Rp0</strong><label class="quote-item-discount" hidden><span><input data-discount-check type="checkbox"> Diskon</span><input data-item-discount type="number" min="0" max="100" value="0" disabled> %</label><label class="bsm-tentative"><input data-tentative type="checkbox"> Tentatif <input data-tentative-date type="date" disabled></label></td><td>'+B('remove-item','×')+'</td></tr>');estimate()}
function estimate(){setupSignature();const f=document.querySelector('#proDirectForm');if(!f)return;const days=Math.max(0,Math.round((new Date(f.elements.end.value)-new Date(f.elements.start.value))/86400000)+1),rows=[...f.querySelectorAll('.pro-item-row')];let subtotal=0,finalTotal=0;const discountMode=f.elements.discount_mode.value,freeDays=Number(f.elements.free_days.value||0),discountValue=Number(f.elements.discount_value.value||0);f.querySelector('[data-free-days]').hidden=discountMode!=='days';f.querySelector('[data-discount-value]').hidden=!['overall_percent','fixed'].includes(discountMode);f.querySelector('#discountValueLabel').textContent=discountMode==='overall_percent'?'Persentase diskon (%)':'Nominal potongan (Rp)';f.elements.discount_value.max=discountMode==='overall_percent'?100:'';f.elements.free_days.max=days;rows.forEach((r,i)=>{const p=stock.find(p=>p.id===r.querySelector('[data-item]').value),price=quotePrice(p),qty=Number(r.querySelector('[data-quantity]').value||0),amount=price*qty*days;subtotal+=amount;const enabled=discountMode==='product'&&r.querySelector('[data-discount-check]').checked;r.querySelector('[data-item-discount]').disabled=!enabled;const percent=enabled?Number(r.querySelector('[data-item-discount]').value||0):0,charged=discountMode==='days'?Math.max(0,days-freeDays):days,finalAmount=Math.round(price*qty*charged*(1-percent/100));finalTotal+=finalAmount;r.querySelector('.quote-item-discount').hidden=discountMode!=='product';r.querySelector('[data-row-number]').textContent=i+1;r.querySelector('[data-row-days]').textContent=days;r.querySelector('[data-row-price]').textContent=M(price);r.querySelector('[data-row-stock]').textContent=p?'Tersedia '+p.available:'';r.querySelector('[data-tentative-date]').disabled=!r.querySelector('[data-tentative]').checked;r.querySelector('[data-row-amount]').textContent=M(finalAmount)});f.querySelectorAll('[data-editor-category]').forEach(x=>x.remove());let previous='';rows.forEach(r=>{const id=r.querySelector('[data-item]').value;if(!id)return;const cfg=window.RENTCAM_CMS_CONFIG||{},p={...(cfg.customProducts||[]).find(x=>x.id===id),...cfg.productOverrides?.[id]},cat=(cfg.mainCategories||[]).find(c=>c.id===p.mainCategory)?.name||p.category||'Equipment Rental';if(cat!==previous){r.insertAdjacentHTML('beforebegin','<tr class="qd-category" data-editor-category><td colspan="7">'+E(cat)+'</td></tr>');previous=cat}});f.querySelector('#quotationDays').textContent=days+' hari';f.querySelector('#quotationSubtotal').textContent=M(subtotal);const overallDiscount=discountMode==='overall_percent'?Math.round(finalTotal*Math.min(100,discountValue)/100):discountMode==='fixed'?Math.min(finalTotal,discountValue):0;finalTotal-=overallDiscount;const tax=f.elements.tax_enabled.checked?Math.round(finalTotal*.11):0;f.querySelector('#quoteDiscountValue').textContent=M(subtotal-finalTotal);f.querySelector('#quoteAfterDiscount').textContent=M(finalTotal);f.querySelector('#quoteTaxValue').textContent=M(tax);f.querySelector('#quoteFinalValue').textContent=M(finalTotal+tax)}

