function moneySum(arr,key='total'){return arr.reduce((s,x)=>s+Number(x?.[key]||0),0)}
function periodOrders(start=today().slice(0,7)+'-01',end=today()){return orders.filter(o=>(o.start_date||o.created_at||'')>=start&&(o.start_date||o.created_at||'')<=end&&o.rental_status!=='cancelled')}
function financeBoard(title,desc,cards,body){return `<div class="pro-finance-board"><div class="pro-card pro-report-hero"><div><small>FINANCE CONTROL</small><h2>${E(title)}</h2><p>${E(desc)}</p></div><div class="pro-report-actions">${B('go-reports','Laporan utama')}${B('go-journal','Jurnal')}</div></div>${stats(cards)}${body}</div>`}
